.step-indicator ol {
    counter-reset: step;
    position: relative;
}

.step-item {
    position: relative;
}

.step-item + .step-item::before {
    content: "";
    position: absolute;
    top: 18px;
    left: -50%;
    right: 50%;
    height: 2px;
    background-color: #dee2e6;
    z-index: 0;
}

.step-item.completed + .step-item::before,
.step-item.completed + .step-item.active::before {
    background-color: #198754;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.875rem;
    position: relative;
    z-index: 1;
}

.step-item.active .step-circle {
    background-color: #0d6efd;
    color: white;
}

.step-item.completed .step-circle {
    background-color: #198754;
    color: white;
}

.step-item.future .step-circle {
    background-color: #dee2e6;
    color: #6c757d;
}

.step-label {
    display: block;
    font-size: 0.75rem;
    margin-top: 0.25rem;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-btn {
    color: inherit;
    border: none;
    background: none;
    cursor: pointer;
}

.step-btn:hover .step-circle {
    opacity: 0.8;
}

.step-btn:hover .step-label {
    text-decoration: underline;
}

::deep .last-no-border:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}

