 <div class="card mb-3">
     <div class="card-body">
         @if (CanRemove)
         {
             <div class="d-flex justify-content-between align-items-start mb-2">
                 <h6 class="card-title mb-0">Position @(Index + 1)</h6>
                 <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
             </div>
         }
         else
         {
             <h6 class="card-title">Position @(Index + 1)</h6>
         }

         <div class="row g-3">
             <div class="col-md-6">
                 <label class="form-label">Company Name *</label>
                 <input type="text" class="form-control" value="@Entry.Company"
                        @onchange="e => { Entry.Company = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Job Title *</label>
                 <input type="text" class="form-control" value="@Entry.Title"
                        @onchange="e => { Entry.Title = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-4">
                 <label class="form-label">Start Date *</label>
                 <input type="date" class="form-control" value="@Entry.StartDate?.ToString("yyyy-MM-dd")"
                        @onchange="e => { Entry.StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-4">
                 <label class="form-label">End Date</label>
                 <input type="date" class="form-control" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@Entry.IsCurrent"
                        @onchange="e => { Entry.EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-4 d-flex align-items-end">
                 <div class="form-check mb-2">
                     <input type="checkbox" class="form-check-input" id="current-@Index" checked="@Entry.IsCurrent"
                            @onchange="e => { Entry.IsCurrent = (bool)(e.Value ?? false); if (Entry.IsCurrent) Entry.EndDate = null; OnChanged.InvokeAsync(); }" />
                     <label class="form-check-label" for="current-@Index">Currently working here</label>
                 </div>
             </div>
             <div class="col-12">
                 <label class="form-label">Description</label>
                 <textarea class="form-control" rows="3" value="@Entry.Description"
                           @onchange="e => { Entry.Description = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }"></textarea>
             </div>
         </div>
     </div>
 </div>

