     <div class="card-body">
         <div class="d-flex justify-content-between align-items-start mb-2">
             <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
             @if (CanRemove)
             {
                 <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
             }
         </div>

         <div class="row g-3">
             <div class="col-md-6">
                 <label class="form-label">Name *</label>
                 <input type="text" class="form-control" value="@Reference.Name"
                        @onchange="e => { Reference.Name = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Relationship *</label>
                 <input type="text" class="form-control" value="@Reference.Relationship"
                        @onchange="e => { Reference.Relationship = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Email *</label>
                 <input type="email" class="form-control" value="@Reference.Email"
                        @onchange="e => { Reference.Email = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }" />
             </div>
             <div class="col-md-6">
                 <label class="form-label">Phone *</label>
                 <input type="tel" class="form-control" value="@Reference.Phone"
                        @onchange="e => { Reference.Phone = e.Value?.ToString() ?? ""; OnChanged.InvokeAsync(); }" />
             </div>
         </div>
     </div>
 </div>

 @code {
